const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

const requestId = body.requestId || ('proposal-' + Date.now());
const category = String(body.category || '').toLowerCase().trim();
const businessName = String(body.businessName || '').trim();
const contactName = String(body.contactName || '').trim();
const contactRole = String(body.contactRole || '').trim();
const contactEmail = String(body.contactEmail || '').trim();
const mode = body.mode === 'deep' ? 'deep' : 'standard';
const selectedOpportunities = Array.isArray(body.selectedOpportunities) ? body.selectedOpportunities : [];
const currentTools = body.currentTools || '';
const scale = body.scale || '';
const integrationNeeds = body.integrationNeeds || '';
const currentSystem = String(body.currentSystem || '').trim();
const senderEmail = String(body.senderEmail || '').trim();
const diagnosticFinding = body.diagnosticFinding && typeof body.diagnosticFinding === 'object' ? body.diagnosticFinding : {};
const clientIp = String(headers['x-forwarded-for'] || '').split(',')[0].trim();

const missingFields = !businessName || !category || !contactEmail || selectedOpportunities.length === 0 || !diagnosticFinding.description;

return [{ json: {
  requestId: requestId, category: category, businessName: businessName, contactName: contactName, contactRole: contactRole,
  contactEmail: contactEmail, mode: mode, selectedOpportunities: selectedOpportunities, currentTools: currentTools,
  scale: scale, integrationNeeds: integrationNeeds, currentSystem: currentSystem, senderEmail: senderEmail,
  diagnosticFinding: diagnosticFinding, clientIp: clientIp, missingFields: missingFields
} }];

