};
const template = TEMPLATE_LIBRARY[input.category] || null;
const isDeepMode = input.mode === 'deep';
const templateMatched = !isDeepMode && !!template && !!template.simple;
return [{ json: {
  requestId: input.requestId, category: input.category, businessName: input.businessName,
  contactName: input.contactName, contactRole: input.contactRole, contactEmail: input.contactEmail,
  mode: input.mode, selectedOpportunities: input.selectedOpportunities, currentTools: input.currentTools,
