const ctx = $input.first().json;

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function genToken() {
  return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10) + '-' + Math.random().toString(36).slice(2, 10);
}

// Mirrors tools/validate_client_document.js -- n8n's Code node sandbox has no
// filesystem access to the repo, so the rule set is duplicated here. NOTE:
// bare "test" is intentionally NOT banned -- the spec requires "tested before"
// as honest library-build language. Only targeted internal-artifact patterns
// are blocked.
function validate(doc) {
  const errors = [];
  if (String(doc.opportunityNamed || '').trim() !== String(doc.opportunityBuilt || '').trim()) errors.push('opportunity named does not match opportunity built');
  ['businessName','automationName','trigger','builtOn'].forEach(function(f) { if (!String(doc[f] || '').trim()) errors.push('empty field: ' + f); });
  (doc.integrations || []).forEach(function(v) { if (/\s\/\s/.test(v)) errors.push('slash-alternative integration: ' + v); if (/\bn8n\b/i.test(v)) errors.push('n8n listed as integration: ' + v); });
  (doc.steps || []).forEach(function(s) { if (/\bn8n\b/i.test(s)) errors.push('n8n mentioned in a step: ' + s); });
  const blocked = ['judge','competition','preset','auto-generated','placeholder','lorem','template','demo'];
  const haystack = [doc.opportunityNamed, doc.businessName, doc.automationName, doc.fullText].filter(Boolean).join(' \n ');
  blocked.forEach(function(t) { if (new RegExp('\\b' + t + '\\b','i').test(haystack)) errors.push('blocked token: ' + t); });
  if (/competition\s+demo/i.test(haystack)) errors.push('blocked phrase: competition demo');
  if (/\bQA-TEST\b/i.test(haystack) || /\btest\s+mode\b/i.test(haystack) || /\bin\s+test\b/i.test(haystack)) errors.push('internal test-artifact pattern found');
  if (/auto-?generated from/i.test(haystack)) errors.push('discloses generation machinery');
  const steps = doc.steps || [];
  if (steps.length && (steps.length < 4 || steps.length > 8)) errors.push('step count out of range: ' + steps.length);
  steps.forEach(function(s) { if (String(s).trim().split(/\s+/).length > 20) errors.push('step over 20 words: ' + s); if (/^\s*\d+[.)]\s/.test(s)) errors.push('step carries manual number into auto-numbered list: ' + s); });
  ['referenceNumber','issueDate','preparedBy','preparedByContact','version'].forEach(function(f) { if (!String((doc.header||{})[f] || '').trim()) errors.push('missing header field: ' + f); });
  if (/pdfshift|created via|powered by/i.test(haystack)) errors.push('vendor footer present');
  return errors;
}

const isLibrary = !!ctx.templateMatched;
const t = ctx.template;
const opportunityName = isLibrary ? t.name : ('Custom automation for ' + ctx.businessName);
const trigger = isLibrary ? t.trigger : 'To be defined with you after approval, based on your process';
const steps = isLibrary ? t.steps : [];
const integrations = isLibrary ? t.integrations : [];
const builtOn = 'n8n';
const requirements = isLibrary ? t.requirements.map(function(r, i) {
  if (i === 0 && ctx.currentSystem) return Object.assign({}, r, { item: 'Access to ' + ctx.currentSystem + ' (what you told us you use for this)' });
  if (i === 2 && ctx.senderEmail) return Object.assign({}, r, { item: 'Confirmations to be sent from ' + ctx.senderEmail });
  return r;
}) : [
  { item: 'A working session to map your current process', reason: 'Custom builds start from your actual workflow, not a template', owner: 'Your operations lead', due: 'Within 3 days of approval' },
  { item: 'Access to the systems involved in that process', reason: 'To confirm what the automation needs to connect to', owner: 'Your IT contact', due: 'Within 5 days of approval' }
];
const notInScope = isLibrary ? t.notInScope : 'anything outside what is scoped during the working session above';

const today = new Date().toISOString().slice(0, 10);
const deadline = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const slug = esc(ctx.businessName).replace(/[^a-zA-Z0-9]+/g,'').slice(0,12).toUpperCase();
const proposalRef = 'LG-' + today.replace(/-/g,'') + '-' + slug + '-01';
const approvalId = 'AP-' + Date.now().toString(36).toUpperCase();
const token = genToken();

const oppsHtml = (ctx.selectedOpportunities || []).map(function(o) { return '<li>' + esc(typeof o === 'string' ? o : (o.title || JSON.stringify(o))) + '</li>'; }).join('');
const stepsHtml = steps.map(function(s) { return '<li>' + esc(s) + '</li>'; }).join('');
const reqRows = requirements.map(function(r) { return '<tr><td>' + esc(r.item) + '</td><td>' + esc(r.reason) + '</td><td>' + esc(r.owner) + '</td><td>' + esc(r.due) + '</td></tr>'; }).join('');
const finding = ctx.diagnosticFinding || {};

const doc = {
  opportunityNamed: opportunityName,
  opportunityBuilt: opportunityName,
  businessName: ctx.businessName,
  automationName: opportunityName,
  trigger: trigger,
  builtOn: builtOn,
  integrations: integrations,
  steps: steps,
  header: { referenceNumber: proposalRef, issueDate: today, preparedBy: 'LordGen AI', preparedByContact: 'zaxellimited360@gmail.com', version: '1.0' }
};
doc.fullText = JSON.stringify(doc) + ' ' + JSON.stringify(requirements) + ' ' + (finding.description || '');
const errors = validate(doc);
if (errors.length) {
  throw new Error('Proposal failed validation, refusing to render: ' + errors.join('; '));
}

const decisionBase = 'https://lordgen-ai-demo.vercel.app/api/decision';
const approveUrl = decisionBase + '?token=' + encodeURIComponent(token) + '&decision=approved';
const changesUrl = decisionBase + '?token=' + encodeURIComponent(token) + '&decision=changes_requested';

const buildTypeLine = isLibrary
  ? (opportunityName + ' -- an automation we have built and tested before, adapted to your ' + ctx.category.replace('_',' ') + ' process.')
  : ('A custom automation for ' + ctx.businessName + ' -- your process needs steps our ready-made automations do not have, so we will design this one specifically for you.');

const summary = 'We reviewed ' + ctx.businessName + ' and found: ' + esc(finding.description) + ' We propose building ' + opportunityName + ' to address this. Once approved, this moves from a manual step to an automated one your team no longer has to think about.';

const docHtml = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>' +
  '@page { size: A4; margin: 0; }' +
  'body { margin:0; font-family: Georgia, "Times New Roman", serif; color:#141312; background:#E8E6E1; }' +
  '.wrap { padding: 40px 56px; }' +
  '.header { background:#0A0A09; color:#E8E6E1; padding:32px 56px; }' +
  '.brand { font-family: Helvetica, Arial, sans-serif; letter-spacing: 3px; font-size: 12px; text-transform: uppercase; color:#C9A24B; margin:0 0 12px 0; }' +
  '.title { font-size: 22px; margin:0; color:#F0E2BC; }' +
  '.docmeta { font-family: Helvetica, Arial, sans-serif; font-size: 10px; color:#8C8A85; margin-top:10px; }' +
  '.rule { height:2px; background:#C9A24B; margin:0; }' +
  '.section { margin: 20px 0; }' +
  '.section h2 { font-family: Helvetica, Arial, sans-serif; font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; color:#8A6A24; border-bottom: 1px solid #C9A24B; padding-bottom: 6px; margin-bottom: 10px; }' +
  '.section p, .section li, .section td { font-size: 12.5px; line-height: 1.55; color:#141312; }' +
  '.section ol, .section ul { margin: 0; padding-left: 20px; }' +
  'table { width:100%; border-collapse: collapse; font-family: Helvetica, Arial, sans-serif; }' +
  'th { text-align:left; font-size:10px; text-transform:uppercase; letter-spacing:0.5px; color:#8A6A24; border-bottom:1px solid #C9A24B; padding:5px 6px; }' +
  'td { border-bottom:1px solid #8C8A85; padding:5px 6px; font-size:11.5px; }' +
  '.decision { background:#141312; color:#E8E6E1; padding:16px 20px; border-left:4px solid #C9A24B; }' +
  '.decision p { color:#E8E6E1; }' +
  '.footer { font-family: Helvetica, Arial, sans-serif; font-size: 10px; color:#8C8A85; text-align:center; margin-top: 20px; }' +
  '</style></head><body>' +
  '<div class="header"><p class="brand">LordGen AI -- Build Proposal</p><h1 class="title">' + esc(opportunityName) + '</h1>' +
  '<div class="docmeta">Ref ' + esc(proposalRef) + ' &nbsp;&middot;&nbsp; Issued ' + esc(today) + ' &nbsp;&middot;&nbsp; Valid until ' + esc(deadline) + ' &nbsp;&middot;&nbsp; Version 1.0<br>Prepared for ' + esc(ctx.businessName) + (ctx.contactName ? (' -- ' + esc(ctx.contactName) + (ctx.contactRole ? (', ' + esc(ctx.contactRole)) : '')) : '') + ' &nbsp;&middot;&nbsp; Prepared by LordGen AI, zaxellimited360@gmail.com</div></div>' +
  '<div class="rule"></div>' +
  '<div class="wrap">' +
  '<div class="section"><h2>Summary</h2><p>' + summary + '</p></div>' +
  '<div class="section"><h2>What We Found</h2><p>' + esc(finding.description) + (finding.evidence ? (' <em>' + esc(finding.evidence) + '</em>') : '') + (finding.source ? ('<br><small>Source: ' + esc(finding.source) + '</small>') : '') + '</p></div>' +
  '<div class="section"><h2>What We Will Build</h2><p>' + buildTypeLine + '</p><p>Opportunities this addresses:</p><ul>' + (oppsHtml || '<li>None specified</li>') + '</ul></div>' +
  '<div class="section"><h2>How It Works</h2><p><strong>Trigger:</strong> ' + esc(trigger) + '</p>' + (stepsHtml ? ('<ol>' + stepsHtml + '</ol>') : '<p>Exact steps are designed with you after approval.</p>') + '</div>' +
  '<div class="section"><h2>What We Need From You</h2><table><tr><th>Item</th><th>Reason</th><th>Owner</th><th>Due</th></tr>' + reqRows + '</table></div>' +
  '<div class="section"><h2>In Scope / Not In Scope</h2><p><strong>In scope:</strong> capture, validation, record write, customer confirmation, run logging.<br><strong>Not in scope:</strong> ' + esc(notInScope) + '.</p></div>' +
  '<div class="section"><h2>Timeline</h2><p>Day 0 approval &middot; Day 3 access confirmed &middot; Day 5 build complete and tested &middot; Day 7 handover and go-live decision.</p></div>' +
  '<div class="section"><h2>Investment</h2><p>Confirmed once this proposal is approved and scope is finalized. There is no cost to receive or approve this proposal.</p></div>' +
  '<div class="section"><h2>Assumptions And Risks</h2><p>This proposal assumes the systems named above can be connected to for reading and writing records. Access arriving later than Day 3 moves every subsequent date by the same amount.</p></div>' +
  '<div class="section decision"><h2 style="color:#C9A24B;border-color:#8A6A24;">Your Decision</h2><p><strong>Approve and start the build</strong> -- we request access the same day and begin.<br><strong>Request changes</strong> -- tell us what to alter and we reissue within two working days.</p><p>Please respond by ' + esc(deadline) + '. After that this proposal expires and is reissued on request.</p></div>' +
  '</div>' +
  '<div class="footer">LordGen AI -- AI Automation Built Around Your Business</div>' +
  '</body></html>';

const emailHtml = '<div style="font-family:Georgia,serif;color:#141312;max-width:560px;">' +
  '<p>Hi' + (ctx.contactName ? (' ' + esc(ctx.contactName)) : '') + ',</p>' +
  '<p>We propose building <strong>' + esc(opportunityName) + '</strong> for ' + esc(ctx.businessName) + '.</p>' +
  '<p>' + summary + '</p>' +
  '<p><strong>What we need from you if you approve:</strong></p><ul>' + requirements.map(function(r) { return '<li>' + esc(r.item) + '</li>'; }).join('') + '</ul>' +
  '<p style="margin:24px 0;">' +
  '<a href="' + approveUrl + '" style="background:#0A0A09;color:#F0E2BC;padding:12px 20px;text-decoration:none;font-family:Helvetica,Arial,sans-serif;font-size:13px;letter-spacing:0.5px;border:1px solid #C9A24B;">Approve and start the build</a>' +
  '&nbsp;&nbsp;' +
  '<a href="' + changesUrl + '" style="background:transparent;color:#141312;padding:12px 20px;text-decoration:none;font-family:Helvetica,Arial,sans-serif;font-size:13px;letter-spacing:0.5px;border:1px solid #8C8A85;">Request changes</a>' +
  '</p>' +
  '<p>Please respond by <strong>' + esc(deadline) + '</strong>. After that this proposal expires.</p>' +
  '<p>Questions? Reply to this email or reach LordGen AI directly at zaxellimited360@gmail.com.</p>' +
  '<p>-- LordGen AI</p>' +
  '</div>';

return [{ json: {
  requestId: ctx.requestId, category: ctx.category, businessName: ctx.businessName, contactName: ctx.contactName, contactRole: ctx.contactRole, contactEmail: ctx.contactEmail,
  mode: ctx.mode, selectedOpportunities: ctx.selectedOpportunities, diagnosticFinding: ctx.diagnosticFinding, categoryEducation: (ctx.template && ctx.template.categoryEducation) || null,
  proposalRef: proposalRef, approvalId: approvalId, token: token, expiresAt: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
  opportunityBuilt: opportunityName, buildType: isLibrary ? 'library' : 'custom',
  subject: 'Your automation build is ready for approval -- ' + ctx.businessName + ' (' + proposalRef + ')',
  docHtml: docHtml, emailHtml: emailHtml, emailSent: false, emailStatus: ''
} }];

const item = $input.first();
const ctx = $('Build Proposal Content').first().json;
const safeName = (ctx.businessName || 'proposal').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
if (item.binary && item.binary.data) {
  item.binary.data.fileName = 'LordGen-Proposal-' + safeName + '.pdf';
  item.binary.data.mimeType = 'application/pdf';
}
return [item];

const ctx = $input.first().json;
return [{ json: {
  requestId: ctx.requestId, category: ctx.category, businessName: ctx.businessName,
  status: 'proposal_issued', demo: false,
  proposalRef: ctx.proposalRef, approvalId: ctx.approvalId, token: ctx.token, expiresAt: ctx.expiresAt,
  opportunityBuilt: ctx.opportunityBuilt, buildType: ctx.buildType,
  emailSent: ctx.emailSent, emailStatus: ctx.emailStatus
} }];

